			CloseMessageWindow(); // flag-less, inlined @01bf1690
			Close(false);
			if (!_cancelFade)
				_onCancel?.Invoke();
		}
		private void ShowDefaultMessageWindow(bool firstOpen = false) {
			if (_closed)
			{
				_input.inputEnabled = false;
				return;
			}
			if (firstOpen)
			{
				_input.inputEnabled = false;
				ShowInputCloseMessageWindow("dlp_net_union_room", "DLP_net_union_room_041", () => _input.inputEnabled = true); // flag-less, inlined @01bf3270
			}
			else
			{
				_input.inputEnabled = true;
				CloseMessageWindow(); // flag-less, inlined @01bf32e0
			}
		}
		private void ShowInputCloseMessageWindow(string msbt, string label, global::System.Action onCloseed = null) {
			_msgWindow.ChangeMSBTFile(msbt);
			_msgWindow.ShowInputCloseMessage(label, null, onCloseed);
		}
		private void ShowConfirmYesNoMsg(string message, global::System.Action onSelectYes = null, global::System.Action onSelectNo = null) {
			_msgWindow.ChangeMSBTFile("ss_net_net_btl");
			_msgWindow.ShowMessage(message, () =>
			{
				OpenContextMenu(YESNO_CONTEXTMENU_LABELS, select =>
				{
					if (select == 0)
						onSelectYes?.Invoke();
					else
						onSelectNo?.Invoke();
				});
			}, false, false);
		}
		private void CloseMessageWindow() {
			if (_msgWindow.IsOpen)
				_msgWindow.CloseMsgWindow();
		}
		private void OpenContextMenu(string[] contextLabels, global::System.Action<int> onSelect) {
			MsgWindowManager.OpenCustomMenu("ss_net_net_btl", contextLabels, onSelect, ContextMenuWindow.CursorType.Arrow, true, 0, null, AK.EVENTS.UI_COMMON_DECIDE);
		}
		private void CloseContextMenu() {
			MsgWindowManager.Instance.CloseContextMenu();
		}
		public UIBattleMatchingTeamSelect() { }
