		{
			MatchingMenu = 0,
			OpenUIMenu = 1,
			ClosingUIMenu = 2,
			Closed = 3,
		}
		private enum RegulationType
		{
			None = 0,
			Empty = 1,
			NotEnoughNum = 2,
			Legend = 3,
			SamePokemon = 4,
			SameItem = 5,
			Illegal = 6,
		}
	}
